function rows(headers: string[], values: string[][]): SheetRow[] {
  return values.map((source) => {
    const row: SheetRow = {};
    headers.forEach((header, index) => {
      if (header) row[header] = String(source[index] ?? "");
    });
    return row;
  });
}

function dateKey(row: SheetRow) {
  return String(row.Date || row["Game Date"] || "").trim();
}

function propKey(row: SheetRow) {
  return [
    row.Date,
    row["Game ID"],
    row.Team,
    row.Player,
    row.Market,
  ].map((value) => String(value || "").trim()).join("|");
}

function trackerKey(row: SheetRow) {
  return [
    row.Date,
    row["Game ID"],
    row.Team,
    row.Player,
    row.Market,
    row.Pick,
  ].map((value) => String(value || "").trim()).join("|");
}

export async function GET() {
  const beforeProps = await readSportWorksheet("NFL", "prop_projections", PROP_HEADERS);
  const beforeTracker = await readSportWorksheet("NFL", "prop_tracker", TRACKER_HEADERS);

  await upsertSportRows(
    "NFL",
    "prop_projections",
    PROP_HEADERS,
    rows(PROP_HEADERS, PROP_VALUES),
    propKey,
  );
  await upsertSportRows(
    "NFL",
    "prop_tracker",
    TRACKER_HEADERS,
    rows(TRACKER_HEADERS, TRACKER_VALUES),
    trackerKey,
  );

  const afterProps = await readSportWorksheet("NFL", "prop_projections", PROP_HEADERS);
  const afterTracker = await readSportWorksheet("NFL", "prop_tracker", TRACKER_HEADERS);
  const targetDate = "2026-09-14";

  return NextResponse.json({
    repaired: true,
    before: {
      propCount: beforeProps.length,
      todayPropCount: beforeProps.filter((row) => dateKey(row) === targetDate).length,
      propTrackerCount: beforeTracker.length,
      todayTrackedCount: beforeTracker.filter((row) => dateKey(row) === targetDate).length,
    },
    after: {
      propCount: afterProps.length,
      todayPropCount: afterProps.filter((row) => dateKey(row) === targetDate).length,
      propTrackerCount: afterTracker.length,
      todayTrackedCount: afterTracker.filter((row) => dateKey(row) === targetDate).length,
      todayGradedCount: afterProps.filter(
        (row) =>
          dateKey(row) === targetDate &&
          ["a prop", "b prop"].includes(String(row.Grade || "").trim().toLowerCase()),
      ).length,
    },
  });
}
